para.example:
     zval को जानकारी देखाउने


<?php
$a = "new string";
xdebug_debug_zval('a');
?>


     &example.outputs;


a: (refcount=1, is_ref=0)='new string'

     zval को refcount बढाउने


<?php
$a = "new string";
$b = $a;
xdebug_debug_zval( 'a' );
?>


     &example.outputs;


a: (refcount=2, is_ref=0)='new string'

     zval को refcount घटाउने


<?php
$a = "new string";
$c = $b = $a;
xdebug_debug_zval( 'a' );
$b = 42;
xdebug_debug_zval( 'a' );
unset( $c );
xdebug_debug_zval( 'a' );
?>


     &example.outputs;


a: (refcount=3, is_ref=0)='new string'
a: (refcount=2, is_ref=0)='new string'
a: (refcount=1, is_ref=0)='new string'

      array zval बनाउने


<?php
$a = array( 'meaning' => 'life', 'number' => 42 );
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=1, is_ref=0)=array (
   'meaning' => (refcount=1, is_ref=0)='life',
   'number' => (refcount=1, is_ref=0)=42
)



वा ग्राफिकल रूपमा

       सरल array का लागि zvals

      array मा पहिले नै रहेको element थप्ने


<?php
$a = array( 'meaning' => 'life', 'number' => 42 );
$a['life'] = $a['meaning'];
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=1, is_ref=0)=array (
   'meaning' => (refcount=2, is_ref=0)='life',
   'number' => (refcount=1, is_ref=0)=42,
   'life' => (refcount=2, is_ref=0)='life'
)



वा ग्राफिकल रूपमा

       reference सहितको सरल array का लागि zvals

      array बाट element हटाउने


<?php
$a = array( 'meaning' => 'life', 'number' => 42 );
$a['life'] = $a['meaning'];
unset( $a['meaning'], $a['number'] );
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=1, is_ref=0)=array (
   'life' => (refcount=1, is_ref=0)='life'
)

      array लाई आफ्नै element को रूपमा थप्ने


<?php
$a = array( 'one' );
$a[] =& $a;
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=2, is_ref=1)=array (
   0 => (refcount=1, is_ref=0)='one',
   1 => (refcount=2, is_ref=1)=...
)



वा ग्राफिकल रूपमा

       circular reference भएको array का लागि zvals
